  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    if n == 0:
        return {'mst_edges': [], 'total_weight': 0.0}
    # Build edge list
    edges = []
    for u, v, d in distances:
        # canonicalize endpoints: u <= v lexicographically
        if u > v:
            u, v = v, u
        mr = max(core[u], core[v], d)
        edges.append((mr, u, v))
    # Sort by weight, then u, then v (already canonicalized)
    edges.sort(key=lambda e: (e[0], e[1], e[2]))
    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError('Graph is disconnected; cannot form MST')
    return {'mst_edges': mst_edges, 'total_weight': total_weight}
